/// Install the ZCode design system into the egui context.
pub fn install(ctx: &egui::Context, mode: Mode) {
    let p = Palette { mode };
    let mut style = (*ctx.style()).clone();

    // Typography: system sans for UI, the ZCode base size drives the scale.
    let mut ts = std::collections::BTreeMap::new();
    ts.insert(egui::TextStyle::Heading, egui::FontId::proportional(text::XL));
    ts.insert(egui::TextStyle::Body, egui::FontId::proportional(text::BASE));
    ts.insert(egui::TextStyle::Monospace, egui::FontId::monospace(text::SM));
    ts.insert(egui::TextStyle::Button, egui::FontId::proportional(text::BASE));
    ts.insert(egui::TextStyle::Small, egui::FontId::proportional(text::SM));
    style.text_styles = ts;
    style.spacing.item_spacing = egui::vec2(geom::sp(2.0), geom::sp(2.0));
    style.spacing.button_padding = egui::vec2(geom::sp(2.5), geom::sp(1.5));
    style.visuals.button_frame = true;
    style.visuals.widgets.noninteractive.bg_fill = p.surface();
    style.visuals.widgets.inactive.bg_fill = p.surface();
    style.visuals.widgets.hovered.bg_fill = p.hover();
    style.visuals.widgets.active.bg_fill = p.selected();
    style.visuals.selection.bg_fill = p.selected();
    style.visuals.selection.stroke =
        egui::Stroke::new(1.0_f32, p.foreground());
    style.visuals.widgets.noninteractive.fg_stroke =
        egui::Stroke::new(1.0_f32, p.foreground_subtle());
    style.visuals.widgets.inactive.fg_stroke =
        egui::Stroke::new(1.0_f32, p.foreground());
    style.visuals.widgets.hovered.fg_stroke =
        egui::Stroke::new(1.0_f32, p.foreground());
    style.visuals.widgets.active.fg_stroke =
        egui::Stroke::new(1.0_f32, p.foreground());
    style.visuals.popup_shadow = egui::Shadow::NONE;
    style.visuals.window_shadow = egui::Shadow::NONE;
    style.visuals.window_stroke = egui::Stroke::new(1.0_f32, p.border());
    style.visuals.panel_fill = p.background();
    style.visuals.extreme_bg_color = p.sidebar();
    style.visuals.faint_bg_color = p.surface();
    style.visuals.hyperlink_color = p.brand();
    style.visuals.dark_mode = mode == Mode::Dark;
    style.visuals.override_text_color = Some(p.foreground());
    ctx.set_style(style);
}
